You are DSH, a coding agent. You complete tasks in a workspace by calling tools.

# Tools
- read_file: {"action": "tool", "tool": "read_file", "path": "<relative path>"}
- write_file: {"action": "tool", "tool": "write_file", "path": "<relative path>", "content": "<full file content>"}
- edit_file: {"action": "tool", "tool": "edit_file", "path": "<relative path>", "old_text": "<exact existing text>", "new_text": "<replacement>"}
- bash: {"action": "tool", "tool": "bash", "command": "<shell command>"}
- list_files: {"action": "tool", "tool": "list_files"}

# Protocol (CRITICAL)
Every turn you respond with EXACTLY ONE JSON object. No prose. No markdown fences.
The "action" field MUST be either "tool" or "done" (NOT the tool name).
Correct example: {"action": "tool", "tool": "read_file", "path": "stats.ts"}
Wrong example: {"action": "read_file", "path": "stats.ts"}

# Rules
1. Inspect before editing: read_file first, then edit with minimal diffs.
2. Verify your work: run the tests with bash when possible.
3. When the task is complete, respond: {"action": "done", "summary": "<what you did>"}.
4. Budget: at most 12 bash calls. Keep commands short and safe.

[tool read_file stats.test.ts] ok
import { mean, variance, median } from "./stats.ts";

let failures = 0;
function check(name: string, got: number, want: number) {
  const ok = Math.abs(got - want) < 1e-9;
  console.log(`${ok ? "PASS" : "FAIL"} ${name}: got=${got} want=${want}`);
  if (!ok) failures++;
}

check("mean", mean([1, 2, 3, 4]), 2.5);
check("variance (sample, n-1)", variance([2, 4, 4, 4, 5, 5, 7, 9]), 32 / 7);
check("median odd", median([3, 1, 2]), 2);
check("median even", median([4, 1, 3, 2]), 2.5);

if (failures > 0) {
  console.error(`\n${failures} test(s) failed`);
  process.exit(1);
}
console.log("\nall tests passed");

[tool read_file stats.ts] ok
// 小型统计库（待修复：variance 分母错误 + median 缺失）
export function mean(xs: number[]): number {
  if (xs.length === 0) return 0;
  const s = xs.reduce((a, x) => a + x, 0);
  return s / xs.length;
}

// BUG: 样本方差应为 n-1 分母，这里误用了 n
export function variance(xs: number[]): number {
  if (xs.length === 0) return 0;
  const m = mean(xs);
  const s = xs.reduce((a, x) => a + (x - m) ** 2, 0);
  return s / (xs.length - 1);
}

export function median(xs: number[]): number {
  if (xs.length === 0) return 0;
  const sorted = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

